/**
 * Loads a LOLA heightmap patch (Float32 .bin + meta JSON, generated by
 * scripts/horizon_masks.py) and builds a displaced terrain mesh in the site's
 * local ENU frame (x = east, y = north, z = up), including the curvature drop
 * d^2/(2R) so the mesh edge falls below the site's horizontal exactly like
 * the horizon masks assume. Vertical exaggeration is a display option
 * (default 3x for readability at these gentle regional slopes; 1x gives
 * true-scale geometry and therefore true-scale shadows).
 */
import * as THREE from 'three';

const R_MOON_M = 1_737_400;
export const PATCH_SCENE_SIZE = 3.2;      // scene units across the 96 km patch
const MESH_N = 384;                        // vertices per side (decimate 768 -> 384)

const cache = new Map();

export async function loadTerrain(siteId) {
  if (cache.has(siteId)) return cache.get(siteId);
  try {
    const base = import.meta.env.BASE_URL || './';
    const meta = await fetch(`${base}terrain/${siteId}.json`).then((r) => { if (!r.ok) throw 0; return r.json(); });
    // terrain-RGB PNG: height = offsetM + (R<<16 | G<<8 | B) * scaleM
    const img = new Image();
    img.src = `${base}terrain/${siteId}.png`;
    await img.decode();
    const cv = document.createElement('canvas');
    cv.width = meta.sizePx; cv.height = meta.sizePx;
    const ctx = cv.getContext('2d', { willReadFrequently: true });
    ctx.drawImage(img, 0, 0);
    const px = ctx.getImageData(0, 0, meta.sizePx, meta.sizePx).data;
    const { offsetM, scaleM } = meta.encoding;
    const grid = new Float32Array(meta.sizePx * meta.sizePx);
    for (let i = 0; i < grid.length; i++) {
      const k = i * 4;
      grid[i] = offsetM + ((px[k] << 16) | (px[k + 1] << 8) | px[k + 2]) * scaleM;
    }
    const data = { meta, grid };
    cache.set(siteId, data);
    return data;
  } catch {
    cache.set(siteId, null);
    return null;
  }
}

/**
 * Build a THREE.Mesh for the patch. Grid rows follow map-plane y, columns map
 * x; local ENU is a rotation of (dx, dy) by the site longitude (see
 * horizon_masks.py conventions): e = dx cosL + dy sinL, n = -dx sinL + dy cosL.
 * We bake the rotation into the vertex positions directly.
 */
export function buildTerrainMesh({ meta, grid }, exaggeration = 1) {
  const N = meta.sizePx;                 // 768
  const half = meta.halfSizeM;           // 48000 m
  const S = PATCH_SCENE_SIZE / (2 * half); // meters -> scene units
  const SZ = S * exaggeration;             // vertical scale
  const lam = (meta.lon * Math.PI) / 180;
  const cl = Math.cos(lam), sl = Math.sin(lam);

  // site height = grid center
  const c = (N - 1) / 2;
  const h0 = grid[Math.round(c) * N + Math.round(c)];

  const geo = new THREE.BufferGeometry();
  const M = MESH_N;
  const pos = new Float32Array(M * M * 3);
  const step = (N - 1) / (M - 1);
  let minZ = Infinity, maxZ = -Infinity;
  for (let j = 0; j < M; j++) {
    const gj = Math.min(N - 1, Math.round(j * step));
    const dy = (gj / (N - 1)) * 2 * half - half;      // map-plane y (m)
    for (let i = 0; i < M; i++) {
      const gi = Math.min(N - 1, Math.round(i * step));
      const dx = (gi / (N - 1)) * 2 * half - half;    // map-plane x (m)
      const h = grid[gj * N + gi];
      const d2 = dx * dx + dy * dy;
      const e = dx * cl + dy * sl;
      const n = -dx * sl + dy * cl;
      const z = (h - h0 - d2 / (2 * R_MOON_M)) * SZ;
      const k = (j * M + i) * 3;
      pos[k] = e * S; pos[k + 1] = n * S; pos[k + 2] = z;
      if (z < minZ) minZ = z;
      if (z > maxZ) maxZ = z;
    }
  }
  const idx = [];
  for (let j = 0; j < M - 1; j++) {
    for (let i = 0; i < M - 1; i++) {
      const a = j * M + i, b = a + 1, cc = a + M, dd = cc + 1;
      idx.push(a, cc, b, b, cc, dd);
    }
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setIndex(idx);
  geo.computeVertexNormals();

  // Bake height + slope shading into vertex colors so the relief stays
  // readable even in lunar night / grazing light (the fill lights are dim).
  const nrm = geo.getAttribute('normal');
  const col = new Float32Array(M * M * 3);
  const zSpan = Math.max(1e-6, maxZ - minZ);
  for (let v = 0; v < M * M; v++) {
    const z = pos[v * 3 + 2];
    const t = (z - minZ) / zSpan;                  // 0 low .. 1 high
    const slope = Math.max(0, nrm.getZ(v));        // 1 flat .. 0 cliff
    const shade = (0.45 + 0.55 * t) * (0.55 + 0.45 * slope);
    col[v * 3] = 0.72 * shade;
    col[v * 3 + 1] = 0.70 * shade;
    col[v * 3 + 2] = 0.66 * shade;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));

  const mat = new THREE.MeshStandardMaterial({
    color: 0xffffff, vertexColors: true, roughness: 0.97, metalness: 0.0,
    flatShading: false,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return { mesh, minZ, maxZ, h0 };
}
